import { test, expect } from '@playwright/test';

test.describe('Password Strength Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/signup');
  });

  test('should display password strength indicator with appropriate feedback', async ({ page }) => {
    // Verify password input field is visible
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();

    // Verify strength indicator is visible
    const strengthIndicator = page.getByRole('status', { name: /password strength/i });
    await expect(strengthIndicator).toBeVisible();

    // Set weak password
    await passwordInput.fill('password123');
    const weakIndicator = page.getByText('Weak');
    await expect(weakIndicator).toBeVisible();

    // Set medium password
    await passwordInput.fill('Password123');
    const mediumIndicator = page.getByText('Medium');
    await expect(mediumIndicator).toBeVisible();

    // Set strong password
    await passwordInput.fill('P@ssword123!');
    const strongIndicator = page.getByText('Strong');
    await expect(strongIndicator).toBeVisible();

    // Verify password confirmation field is visible
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await expect(confirmPasswordInput).toBeVisible();
  });

  test('should handle edge cases for password strength indicator', async ({ page }) => {
    // Verify password input field is visible
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();

    // Set empty password
    await passwordInput.fill('');
    const emptyIndicator = page.getByText('Too short');
    await expect(emptyIndicator).toBeVisible();

    // Set password with special characters only
    await passwordInput.fill('!#$%^&*');
    const weakIndicator = page.getByText('Weak');
    await expect(weakIndicator).toBeVisible();

    // Set password with numbers only
    await passwordInput.fill('12349');
    const weakIndicator2 = page.getByText('Weak');
    await expect(weakIndicator2).toBeVisible();

    // Set password with mixed case and special characters
    await passwordInput.fill('P@ssword123!');
    const strongIndicator = page.getByText('Strong');
    await expect(strongIndicator).toBeVisible();

    // Verify error message appears when passwords do not match
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('wrongpassword');
    const errorMsg = page.getByText('Passwords and confirmations do not match');
    await expect(errorMsg).toBeVisible();
  });
});
